    const lossFields=`${field('Annual loss input type','lossMode',lossMode,'select',{options:['estimated','measured']})}${field('Estimated annual loss rate (fraction/year)','lossRate',a.lossRate??'','number',{min:0,max:1,step:'any',hint:'A value of 0.01 means 1% per year.'})}${field('Measured annual loss (kg/year)','measuredLoss',a.measuredLoss??'','number',{min:0,step:'any',hint:'Enter the recorded annual mass loss.'})}${field('Loss source / provenance','lossSource',a.lossSource||'','text',{full:true,placeholder:'Metered record, maintenance log, engineering estimate…'})}`;
    const technical=`${field('Manufacturer / model','manufacturer',a.manufacturer||'')}${field('Electrical characteristics','characteristics',a.characteristics||'','text',{placeholder:'e.g. 50 kA interrupting, 60 Hz',full:true})}${field('Asset condition','condition',a.condition||'Unknown','select',{options:['Unknown','Good','Fair','Poor']})}${field('Maintenance notes','maintenanceNotes',a.maintenanceNotes||'','textarea',{full:true})}${field('Custom attributes (JSON)','customAttributesText',a.customAttributes?JSON.stringify(a.customAttributes,null,2):'','textarea',{full:true,hint:'Optional equipment-specific fields as a JSON object.'})}`;
