      if(customAttributes===null||typeof customAttributes!=='object'||Array.isArray(customAttributes))throw Error('Custom attributes must be a JSON object.');
      const item={...a,id:a.id||uid(),assetId:d.assetId.trim(),site:d.site.trim(),category:d.category,manufacturer:d.manufacturer,voltageKv:Number(d.voltageKv),characteristics:d.characteristics,capacityKg:Number(d.capacityKg),installYear:Number(d.installYear),retirementYear:Number(d.retirementYear),lossMode:mode,lossSource:d.lossSource,condition:d.condition,maintenanceNotes:d.maintenanceNotes,customAttributes,remainingGasKg:d.remainingGasKg===''||d.remainingGasKg===undefined?null:Number(d.remainingGasKg),recoveryEfficiency:d.recoveryEfficiency===''||d.recoveryEfficiency===undefined?null:Number(d.recoveryEfficiency),annualOpex:Number(d.annualOpex)||0,annualMaintenance:Number(d.annualMaintenance)||0,capex:Number(d.capex)||0,installCost:Number(d.installCost)||0,decommissionCost:Number(d.decommissionCost)||0,recoveryCost:Number(d.recoveryCost)||0};
      if(item.retirementYear<item.installYear)throw Error('Retirement year must be on or after installation year.');
