      if(mode==='measured'){delete item.lossRate;if(d.measuredLoss!==''&&d.measuredLoss!==undefined){item.measuredLoss=Number(d.measuredLoss);if(!d.lossSource.trim())throw Error('Add the source for this measured loss value.')}else delete item.measuredLoss}
      else{delete item.measuredLoss;if(d.lossRate!==''&&d.lossRate!==undefined){item.lossRate=Number(d.lossRate);if(!d.lossSource.trim())throw Error('Add the source for this estimated loss rate.')}else delete item.lossRate}
